use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let matrix = input.as_array().unwrap();
    let n = matrix.len();
    let mut main_diagonal_sum = 0;
    let mut anti_diagonal_sum = 0;

    for i in 0..n {
        main_diagonal_sum += matrix[i][i] as i64;
        anti_diagonal_sum += matrix[i][n - 1 - i] as i64;
    }

    Value::Array(vec![
        Value::Number(main_diagonal_sum.into()),
        Value::Number(anti_diagonal_sum.into()),
    ])
}
